import { View, Text, Pressable, Animated, StyleSheet } from "react-native";
import { useRef } from "react";
import { registerRootComponent } from "expo";

function App() {
  const fade = useRef(new Animated.Value(0)).current;
  const h = useRef(new Animated.Value(0)).current;
  const show = () => {
    Animated.parallel([
      Animated.timing(fade, { toValue: 1, duration: 300 }),
      Animated.timing(h, { toValue: 60, duration: 300 }),
    ]).start();
  };
  return (
    <View style={styles.s}>
      <Pressable nativeID="show" style={styles.b} onPress={show}><Text style={styles.t}>Амжилт</Text></Pressable>
      <Animated.View nativeID="toast" style={[styles.toast, { opacity: fade, height: h }]}>
        <Text style={styles.toastText}>Захиалга баталгаажлаа</Text>
      </Animated.View>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 20, padding: 24, alignItems: "center", justifyContent: "center" },
  b: { backgroundColor: "#16a34a", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
  toast: { overflow: "hidden", backgroundColor: "#16a34a", borderRadius: 12, justifyContent: "center", paddingHorizontal: 16 }, toastText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
